using System;
using System.Diagnostics;
using System.Reflection;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Tests;

/// <summary>
/// Marker attribute that specifies a performance warning threshold for a test method.
/// In MSTest 4.x, TestMethodAttribute.Execute is no longer virtual, so timing is
/// handled via TestInitialize/TestCleanup in a base class instead.
/// </summary>
[AttributeUsage(AttributeTargets.Method, AllowMultiple = false)]
public sealed class TimedTestMethodAttribute : TestMethodAttribute
{
    public int WarningThresholdMs { get; }

    public TimedTestMethodAttribute(int warningThresholdMs = 5000)
    {
        WarningThresholdMs = warningThresholdMs;
    }
}

/// <summary>
/// Base class that provides automatic performance timing for tests decorated with
/// [TimedTestMethod]. Replaces the former Execute override pattern.
/// </summary>
public abstract class TimedTestBase
{
    public TestContext TestContext { get; set; } = null!;

    private Stopwatch? _stopwatch;
    private int _warningThresholdMs;

    [TestInitialize]
    public void TimedTestInitialize()
    {
        var method = GetType().GetMethod(TestContext.TestName!);
        var attr = method?.GetCustomAttribute<TimedTestMethodAttribute>();
        if (attr is not null)
        {
            _warningThresholdMs = attr.WarningThresholdMs;
            _stopwatch = Stopwatch.StartNew();
        }
    }

    [TestCleanup]
    public void TimedTestCleanup()
    {
        if (_stopwatch is not null)
        {
            _stopwatch.Stop();
            if (_stopwatch.ElapsedMilliseconds > _warningThresholdMs)
            {
                Console.WriteLine($"WARNING: {TestContext.TestName} took {_stopwatch.ElapsedMilliseconds}ms (threshold: {_warningThresholdMs}ms)");
            }
        }
    }
}

[TestClass]
public class PerformanceTests : TimedTestBase
{
    [TimedTestMethod(warningThresholdMs: 1000)]
    [Timeout(0)]
    public void ProcessLargeDataSet_CompletesInTime()
    {
        Assert.IsTrue(true);
    }

    [TimedTestMethod]
    public void QuickCalculation_IsFast()
    {
        Assert.IsTrue(true);
    }

    [TestMethod]
    [Timeout(0)]
    public void LongRunningIntegration_NeverTimesOut()
    {
        Assert.IsTrue(true);
    }
}

